// Updates for the session's project: after an update, the products that
// run start again, so the new version is what the owner sees; a new Kobble
// in package.json is installed and the factory starts again on it.
import { CORE_VERSION, RELEASE_SOURCE, releaseOf, run, } from "@software-factory/core";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { CORE_PACKAGE } from "../pin-core.js";
import { servedUpdates } from "./served.js";
export function updatesOf(session, onChange, cards, restartFactory) {
    const { project } = session.options;
    return servedUpdates({
        project,
        onChange,
        restartRunning: async () => {
            const launcher = launcherOf(session);
            if (!launcher)
                return;
            for (const part of launcher.state())
                if (part.area === "products" && part.light === "running")
                    await launcher.restart(part.id);
        },
        install: async () => {
            await run("npm", ["install", "--no-audit", "--no-fund"], {
                cwd: project,
            });
        },
        newKobble: () => {
            const pinned = pinnedKobble(project);
            return pinned !== null && pinned !== releaseOf(CORE_VERSION);
        },
        ...(restartFactory
            ? {
                restartFactory: () => restartFactory((launcherOf(session)?.state() ?? [])
                    .filter((part) => part.light === "running")
                    .map((part) => part.id)),
            }
            : {}),
        releases: {
            current: CORE_VERSION,
            tags: async () => {
                try {
                    const out = await run("git", ["ls-remote", "--tags", repositoryUrl(), "release-*"], { env: { GIT_TERMINAL_PROMPT: "0" } });
                    return out.split("\n");
                }
                catch {
                    return [];
                }
            },
            cards: () => session.work.view()?.cards ?? [],
            create: (title, body) => cards().create(title, body, "todo"),
        },
    });
}
function launcherOf(session) {
    try {
        return session.launcherOrRefuse();
    }
    catch {
        return null;
    }
}
// The Kobble the project's package.json pins (github:…#release-0.12.0), or
// null when it pins none.
function pinnedKobble(project) {
    const file = join(project, "package.json");
    if (!existsSync(file))
        return null;
    const data = JSON.parse(readFileSync(file, "utf8"));
    return (data.optionalDependencies?.[CORE_PACKAGE] ??
        data.devDependencies?.[CORE_PACKAGE] ??
        data.dependencies?.[CORE_PACKAGE] ??
        null);
}
// github:owner/name → https://github.com/owner/name.git
function repositoryUrl() {
    return `https://github.com/${RELEASE_SOURCE.replace(/^github:/, "")}.git`;
}
